"""
Simpan Video (versi Vercel): TikTok, Instagram, dan X. Tanpa API key.

Struktur repo:
    app.py            <- file ini (termasuk gambar latar, base64)
    requirements.txt

Env var opsional (Vercel > Settings > Environment Variables):
    COOKIES_TEXT   isi lengkap cookies.txt (format Netscape), untuk Instagram
"""
import base64
import os
import re
import urllib.request
from urllib.parse import quote, urlparse

import yt_dlp
from flask import Flask, Response, jsonify, request

app = Flask(__name__)

ALLOWED_DOMAINS = {
    "tiktok": ("tiktok.com",),
    "instagram": ("instagram.com",),
    "x": ("x.com", "twitter.com"),
}
ANSI = re.compile(r"\x1b\[[0-9;]*m")
# Vercel tidak punya ffmpeg: hanya ambil file MP4 progresif (bukan HLS/DASH).
FORMAT = "b[ext=mp4][protocol=https]/b[protocol=https]/b[ext=mp4]"


def platform_of(url):
    try:
        p = urlparse(url)
    except ValueError:
        return None
    if p.scheme not in ("http", "https") or not p.hostname:
        return None
    host = p.hostname.lower()
    for name, domains in ALLOWED_DOMAINS.items():
        if any(host == d or host.endswith("." + d) for d in domains):
            return name
    return None


def base_opts():
    o = {
        "quiet": True,
        "no_warnings": True,
        "noplaylist": True,
        "socket_timeout": 15,
        "cachedir": False,  # filesystem Vercel read-only, kecuali /tmp
        "format": FORMAT,
        "playlist_items": "1",
    }
    text = os.environ.get("COOKIES_TEXT")
    if text:
        path = "/tmp/cookies.txt"
        if not os.path.exists(path):
            with open(path, "w") as f:
                f.write(text)
        o["cookiefile"] = path
    return o


def friendly(err):
    msg = ANSI.sub("", str(err)).lower()
    if "login" in msg or "cookies" in msg or "rate-limit" in msg or "429" in msg:
        return ("Platform meminta login atau memblokir server ini "
                "(sering terjadi di Instagram). Isi env COOKIES_TEXT lalu deploy ulang.")
    if "private" in msg:
        return "Postingan ini privat, jadi tidak bisa diunduh."
    if "unsupported url" in msg:
        return "Link tidak dikenali. Tempel link langsung ke postingan videonya."
    return "Tidak bisa mengambil video dari link ini. Pastikan postingannya publik dan berisi video."


def resolve(url):
    """Kembalikan (info, url_media, header_untuk_request_media)."""
    with yt_dlp.YoutubeDL(base_opts()) as y:
        info = y.extract_info(url, download=False)
        if info.get("_type") == "playlist":
            info = next((e for e in info.get("entries") or [] if e), None)
            if not info:
                raise ValueError("tidak ada video")
        media = info.get("url")
        if not media or info.get("protocol") not in ("http", "https"):
            raise ValueError("format stream tidak didukung")
        headers = dict(info.get("http_headers") or {})
        cookie = y.cookiejar.get_cookie_header(media)
        if cookie:
            headers["Cookie"] = cookie
    return info, media, headers


@app.post("/api/info")
def api_info():
    url = ((request.get_json(silent=True) or {}).get("url") or "").strip()
    plat = platform_of(url)
    if not plat:
        return jsonify(error="Link harus dari TikTok, Instagram, atau X."), 400
    try:
        info, _, _ = resolve(url)
    except Exception as e:
        return jsonify(error=friendly(e)), 400
    return jsonify(
        platform=plat,
        title=info.get("title") or info.get("description") or "Tanpa judul",
        uploader=info.get("uploader") or info.get("channel") or "",
        duration=info.get("duration"),
        thumbnail=info.get("thumbnail"),
    )


@app.get("/api/download")
def api_download():
    url = (request.args.get("url") or "").strip()
    if not platform_of(url):
        return jsonify(error="Link harus dari TikTok, Instagram, atau X."), 400
    try:
        info, media, headers = resolve(url)
        if not media.startswith("https://"):
            raise ValueError("bukan https")
        upstream = urllib.request.urlopen(
            urllib.request.Request(media, headers=headers), timeout=20
        )
    except Exception as e:
        return jsonify(error=friendly(e)), 400

    def stream():
        try:
            while True:
                chunk = upstream.read(64 * 1024)
                if not chunk:
                    break
                yield chunk
        finally:
            upstream.close()

    title = re.sub(r"[^\w\- ]", "", info.get("title") or "")[:60].strip() or info.get("id", "video")
    resp = Response(stream(), mimetype="video/mp4")
    resp.headers["Content-Disposition"] = (
        "attachment; filename=\"video.mp4\"; filename*=UTF-8''" + quote(title + ".mp4")
    )
    length = upstream.headers.get("Content-Length")
    if length:
        resp.headers["Content-Length"] = length
    resp.headers["Cache-Control"] = "no-store"
    return resp


@app.get("/bg.jpg")
def bg():
    return Response(
        base64.b64decode(BG_B64), mimetype="image/jpeg",
        headers={"Cache-Control": "public, max-age=86400"},
    )


@app.get("/")
def index():
    return Response(PAGE, mimetype="text/html")


PAGE = r"""<!doctype html>
<html lang="id">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Simpan Video</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Schibsted+Grotesk:wght@400;500;700&display=swap" rel="stylesheet">
<style>
:root{
  --bg:#E8ECF1; --surface:#FFFFFF; --ink:#16202E; --muted:#5B6779;
  --line:#CBD3DE; --accent:#2F5BFF; --accent-ink:#FFFFFF; --error:#C2331F;
  --panel:rgba(255,255,255,.86); --panel-line:rgba(255,255,255,.6);
  color-scheme:light dark;
}
@media (prefers-color-scheme:dark){
  :root{
    --bg:#0F1620; --surface:#18212E; --ink:#E8EDF4; --muted:#93A0B3;
    --line:#2A3647; --accent:#6C8BFF; --accent-ink:#0F1620; --error:#FF8A75;
    --panel:rgba(15,22,32,.82); --panel-line:rgba(255,255,255,.12);
  }
}
*{box-sizing:border-box}
html,body{margin:0}
body{
  background:var(--bg); color:var(--ink);
  font-family:"Schibsted Grotesk",system-ui,-apple-system,"Segoe UI",sans-serif;
  line-height:1.5; min-height:100vh; min-height:100dvh;
  display:flex; align-items:flex-end; justify-content:center;
  padding:max(16px,env(safe-area-inset-top)) 16px max(16px,env(safe-area-inset-bottom));
}
body::before{
  content:""; position:fixed; inset:0; z-index:-1;
  background:var(--bg) url(/bg.jpg) 50% 25%/cover no-repeat;
}
main{
  width:100%; max-width:480px; padding:24px;
  background:var(--panel); border:1px solid var(--panel-line); border-radius:20px;
  -webkit-backdrop-filter:blur(16px); backdrop-filter:blur(16px);
}
@media (min-width:900px){
  body{align-items:center;justify-content:flex-start;padding-left:6vw}
}
h1{font-size:clamp(1.7rem,6vw,2.4rem);line-height:1.05;letter-spacing:-.03em;font-weight:700;margin:0 0 12px}
.lead{color:var(--muted);margin:0 0 20px;max-width:44ch}
.row{display:flex;gap:8px}
input{
  flex:1;min-width:0;font:inherit;color:inherit;background:var(--surface);
  border:1.5px solid var(--line);border-radius:10px;padding:14px 16px;
}
input:focus-visible,button:focus-visible{outline:3px solid var(--accent);outline-offset:2px}
button{
  font:inherit;font-weight:500;border:0;border-radius:10px;padding:14px 20px;cursor:pointer;
  background:var(--accent);color:var(--accent-ink);
}
button:disabled{opacity:.55;cursor:progress}
.plats{display:flex;gap:16px;margin:14px 2px 0;font-size:.9rem;color:var(--muted)}
.plats span{padding-bottom:2px;border-bottom:2px solid transparent}
.plats span.on{color:var(--ink);font-weight:700;border-color:var(--accent)}
#status{min-height:1.5em;margin:18px 2px 0;color:var(--muted)}
#status.err{color:var(--error)}
#result{
  display:none;margin-top:8px;background:var(--surface);border:1.5px solid var(--line);
  border-radius:16px;overflow:hidden;
}
#result.show{display:block}
#thumb{display:block;width:100%;max-height:320px;object-fit:cover;background:var(--line)}
.body{padding:18px 18px 20px}
#title{margin:0 0 4px;font-weight:700;overflow-wrap:anywhere;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden}
#meta{margin:0 0 16px;color:var(--muted);font-size:.9rem}
footer{margin-top:20px;color:var(--muted);font-size:.85rem;max-width:52ch}
@media (max-width:420px){.row{flex-direction:column}}
</style>
</head>
<body>
<main>
  <h1>Simpan video dari TikTok, Instagram, dan X</h1>
  <p class="lead">Tempel link postingan publik, lalu unduh videonya. Tanpa akun, tanpa API key.</p>

  <form id="f" class="row">
    <input id="url" type="url" inputmode="url" autocomplete="off" required
           placeholder="https://www.tiktok.com/@akun/video/…" aria-label="Link postingan">
    <button id="go" type="submit">Cari video</button>
  </form>
  <div class="plats" aria-hidden="true">
    <span data-p="tiktok">TikTok</span><span data-p="instagram">Instagram</span><span data-p="x">X</span>
  </div>

  <p id="status" role="status" aria-live="polite"></p>

  <section id="result" aria-label="Hasil">
    <img id="thumb" alt="" referrerpolicy="no-referrer">
    <div class="body">
      <p id="title"></p>
      <p id="meta"></p>
      <button id="dl" type="button">Unduh video</button>
    </div>
  </section>

  <footer>Unduh hanya konten milikmu atau yang pemiliknya izinkan. Hormati hak cipta dan aturan tiap platform.</footer>
</main>

<script>
const $ = s => document.querySelector(s);
const urlEl = $('#url'), statusEl = $('#status'), result = $('#result');
let current = '';

const patterns = {
  tiktok: /(^|\/\/|\.)tiktok\.com/i,
  instagram: /(^|\/\/|\.)instagram\.com/i,
  x: /(^|\/\/|\.)(x|twitter)\.com/i
};
urlEl.addEventListener('input', () => {
  const hit = Object.keys(patterns).find(k => patterns[k].test(urlEl.value));
  document.querySelectorAll('[data-p]').forEach(el => el.classList.toggle('on', el.dataset.p === hit));
});

function say(msg, isErr) {
  statusEl.textContent = msg || '';
  statusEl.classList.toggle('err', !!isErr);
}
function fmt(sec) {
  if (!sec) return '';
  const m = Math.floor(sec / 60), s = Math.round(sec % 60);
  return m + ':' + String(s).padStart(2, '0');
}

$('#f').addEventListener('submit', async e => {
  e.preventDefault();
  const btn = $('#go');
  current = urlEl.value.trim();
  result.classList.remove('show');
  say('Mencari video…');
  btn.disabled = true;
  try {
    const r = await fetch('/api/info', {
      method: 'POST',
      headers: {'Content-Type': 'application/json'},
      body: JSON.stringify({url: current})
    });
    const d = await r.json();
    if (!r.ok) throw new Error(d.error || 'Gagal mengambil info video.');
    const thumb = $('#thumb');
    const ok = /^https:/.test(d.thumbnail || '');
    thumb.style.display = ok ? 'block' : 'none';
    if (ok) thumb.src = d.thumbnail;
    $('#title').textContent = d.title;
    $('#meta').textContent = [d.uploader, fmt(d.duration)].filter(Boolean).join(' · ');
    result.classList.add('show');
    say('');
  } catch (err) {
    say(err.message, true);
  } finally {
    btn.disabled = false;
  }
});

$('#dl').addEventListener('click', () => {
  const a = document.createElement('a');
  a.href = '/api/download?url=' + encodeURIComponent(current);
  a.download = '';
  document.body.appendChild(a); a.click(); a.remove();
  say('Unduhan dimulai. Cek folder unduhan atau bilah unduhan browser.');
});
</script>
</body>
</html>
"""

if __name__ == "__main__":
    app.run(host="127.0.0.1", port=int(os.environ.get("PORT", 5000)))


